css:
.flex {
  display: flex
}

.h-12 {
  height: 3rem
}

.w-32 {
  width: 8rem
}

@keyframes spin {
  to {
    transform: rotate(360deg)
  }
}

.animate-spin {
  animation: spin 1s linear infinite
}

.items-center {
  align-items: center
}

.justify-center {
  justify-content: center
}

.rounded-full {
  border-radius: 9999px
}

.border-b-2 {
  border-bottom-width: 2px
}

.border-t-2 {
  border-top-width: 2px
}

.border-blue-900 {
  --tw-border-opacity: 1;
  border-color: rgb(30 58 138 / var(--tw-border-opacity))
}
